@verbatim
<!DOCTYPE html>
<html lang="id" data-theme="dark">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Visage – Makeup Editorial oleh Rima Ayu</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Bodoni+Moda:ital,opsz,wght@0,6..96,500;0,6..96,900;1,6..96,500;1,6..96,900&family=Work+Sans:wght@400;500;600&display=swap">
<style>
:root{--bg:#F7F7F5;--ink:#0B0B0F;--blue:#1F2BFF;--skin:#F1C7B5;--mute:#0B0B0F99;--line:#0B0B0F;--d:'Bodoni Moda','Didot',Georgia,serif;--b:'Work Sans','Helvetica Neue',Arial,sans-serif;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#0B0B0F;--ink:#F7F7F5;--blue:#5A66FF;--mute:#F7F7F599;--line:#F7F7F5}}
:root[data-theme="dark"]{--bg:#0B0B0F;--ink:#F7F7F5;--blue:#5A66FF;--mute:#F7F7F599;--line:#F7F7F5}
html{scroll-behavior:smooth}*{box-sizing:border-box;margin:0}
body{background:var(--bg);color:var(--ink);font:400 16px/1.65 var(--b);overflow-x:hidden}
a{color:inherit;text-decoration:none}button{font:inherit;color:inherit}
header.top{position:sticky;top:0;z-index:60;background:var(--bg);border-bottom:1px solid var(--line);padding-top:env(safe-area-inset-top,0px)}
.bar{display:flex;align-items:center;justify-content:space-between;padding:14px 4vw;gap:20px}
.brand{font:900 italic 30px var(--d);letter-spacing:-.02em}
#menu{display:flex;gap:26px;font-size:13px;font-weight:500;letter-spacing:.14em;text-transform:uppercase}
#menu a{padding:4px 0;border-bottom:2px solid transparent;transition:border-color .2s,color .2s}
#menu a:hover{color:var(--blue)}#menu a.on{border-color:var(--blue)}
.cta{background:var(--blue);color:#fff;padding:10px 22px;font:600 13px var(--b);letter-spacing:.16em;text-transform:uppercase;border:0;cursor:pointer;transition:transform .2s}
.cta:hover{transform:translate(-2px,-2px);box-shadow:4px 4px 0 var(--ink)}
.cta.o{background:none;color:var(--ink);border:1px solid var(--ink)}
#burger{display:none;background:none;border:1px solid var(--line);padding:8px 14px;font:600 12px var(--b);letter-spacing:.14em;cursor:pointer}
.pg{display:none;min-height:80vh}.pg.on{display:block;animation:wipe .8s cubic-bezier(.7,0,.2,1)}
@keyframes wipe{from{clip-path:inset(0 0 100% 0)}to{clip-path:inset(0)}}
.wrap{padding:60px 4vw 100px;max-width:1400px;margin:auto}
.kick{font:600 12px var(--b);letter-spacing:.24em;text-transform:uppercase;color:var(--blue)}
h1,h2{font-family:var(--d);font-weight:900;letter-spacing:-.03em;line-height:.92}
.ph{font-size:clamp(56px,11vw,170px);margin:10px 0 40px;font-style:italic}
.mast{font:900 clamp(90px,26vw,420px)/.78 var(--d);letter-spacing:-.06em;text-align:center;margin:26px 0 0;position:relative;z-index:1}
.cover{display:grid;grid-template-columns:1fr 1.25fr 1fr;gap:3vw;align-items:center;padding:0 4vw 50px;margin-top:-5vw;position:relative;z-index:2}
.cover .l p{max-width:32ch;margin:14px 0 24px}
.eyewrap{aspect-ratio:1;border-radius:50%;background:var(--skin);border:1px solid var(--line);display:grid;place-items:center;position:relative}
.eyewrap::after{content:"Edisi 07";position:absolute;right:2%;top:6%;background:var(--ink);color:var(--bg);font:600 12px var(--b);letter-spacing:.2em;text-transform:uppercase;padding:6px 12px;transform:rotate(8deg)}
.eye{width:86%;animation:bl 5.5s infinite;transform-origin:50% 50%}
@keyframes bl{0%,94%,100%{transform:scaleY(1)}97%{transform:scaleY(.06)}}
.cl{list-style:none;padding:0}.cl li{padding:14px 0;border-top:1px solid var(--line);font:500 italic 24px/1.15 var(--d)}.cl li small{display:block;font:600 11px var(--b);letter-spacing:.2em;text-transform:uppercase;color:var(--blue);margin-bottom:4px;font-style:normal}
.tick{background:var(--ink);color:var(--bg);overflow:hidden;white-space:nowrap;padding:14px 0}
.tick span{display:inline-block;font:italic 500 26px var(--d);animation:mq 34s linear infinite}
@keyframes mq{to{transform:translateX(-50%)}}
.chips{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:34px}
.chips button{border:1px solid var(--line);background:none;padding:7px 18px;font:500 13px var(--b);letter-spacing:.1em;text-transform:uppercase;cursor:pointer}
.chips button.on,.chips button:hover{background:var(--ink);color:var(--bg)}
.mas{columns:3 260px;column-gap:22px}
.sp{break-inside:avoid;margin-bottom:22px;position:relative;overflow:hidden;background:var(--g);color:#fff;display:flex;align-items:flex-end;padding:22px;cursor:pointer;border:1px solid var(--line)}
.sp::before{content:attr(data-n);position:absolute;top:2px;right:14px;font:900 italic 110px/1 var(--d);opacity:.28}
.sp i{position:absolute;left:50%;top:40%;width:44%;aspect-ratio:1;margin:-22% 0 0 -22%;background:var(--s);border-radius:var(--r);transition:transform .8s cubic-bezier(.2,.8,.2,1)}
.sp:hover i{transform:rotate(24deg) scale(1.2)}
.sp div{position:relative;z-index:1}.sp b{font:900 italic 28px/1 var(--d);display:block}.sp small{font:500 11px var(--b);letter-spacing:.2em;text-transform:uppercase;opacity:.85}
.toc{border-top:2px solid var(--line)}
.row{display:grid;grid-template-columns:90px 1fr auto;gap:24px;align-items:center;padding:28px 0;border-bottom:1px solid var(--line);width:100%;background:none;border-inline:0;border-top:0;text-align:left;cursor:pointer;transition:padding .3s,background .3s}
.row:hover{padding-left:16px;background:color-mix(in srgb,var(--blue) 10%,transparent)}
.row .no{font:900 italic 64px/1 var(--d);color:var(--blue)}.row h3{font:900 clamp(28px,3.6vw,48px)/1 var(--d);letter-spacing:-.02em}
.row p{color:var(--mute);margin-top:6px;max-width:52ch}.row b{font:500 italic 28px var(--d);white-space:nowrap}
.two{display:grid;grid-template-columns:1fr 1fr;gap:5vw;align-items:start}
.port{aspect-ratio:3/4;background:var(--skin);border:1px solid var(--line);position:relative;overflow:hidden}
.port::before{content:"";position:absolute;left:12%;right:12%;bottom:0;top:18%;border-radius:999px 999px 0 0;background:var(--blue)}
.port::after{content:"RIMA AYU";position:absolute;left:0;right:0;bottom:6%;text-align:center;font:900 italic 44px var(--d);color:#fff;letter-spacing:.04em}
.cols{columns:2 240px;column-gap:34px}.cols p{margin-bottom:16px}.cols p:first-child::first-letter{font:900 82px/.8 var(--d);float:left;padding:6px 10px 0 0;color:var(--blue)}
.stats{display:flex;gap:4vw;flex-wrap:wrap;margin:44px 0;border-block:1px solid var(--line);padding:26px 0}
.stats div{flex:1 1 140px}.stats b{display:block;font:900 italic clamp(54px,7vw,100px)/1 var(--d);color:var(--blue)}.stats span{font:600 12px var(--b);letter-spacing:.2em;text-transform:uppercase}
.pull{font:500 italic clamp(30px,4.4vw,62px)/1.08 var(--d);padding:30px 0 0;border-top:6px solid var(--blue);margin-top:50px;max-width:20ch}
.jur{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:30px}
.art{border-top:2px solid var(--line);padding-top:18px}.art small{font:600 12px var(--b);letter-spacing:.2em;text-transform:uppercase;color:var(--blue)}
.art h3{font:900 italic 34px/1 var(--d);margin:10px 0}.art summary{cursor:pointer;color:var(--blue);font-weight:600;margin-top:10px}.art p{color:var(--mute);margin-top:8px}
.form{display:grid;grid-template-columns:1fr 1fr;gap:26px;max-width:760px}
.form label{font:600 12px var(--b);letter-spacing:.2em;text-transform:uppercase}.form .f{grid-column:1/-1}
.form input,.form select,.form textarea{width:100%;margin-top:6px;border:0;border-bottom:2px solid var(--line);background:transparent;padding:10px 0;font:400 18px var(--b);color:var(--ink);border-radius:0;resize:none}
.form select option{color:#0B0B0F}
.info{border:1px solid var(--line);padding:30px;background:var(--skin);color:#0B0B0F}.info h3{font:900 italic 36px var(--d)}.info p{margin-top:10px}
footer{border-top:1px solid var(--line);padding:26px 4vw 110px;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;font-size:13px;color:var(--mute)}
#bot{position:fixed;right:16px;bottom:calc(16px + env(safe-area-inset-bottom,0px));z-index:100}
#fab{width:70px;height:70px;border:0;background:var(--blue);color:#fff;font:900 italic 26px var(--d);cursor:pointer;box-shadow:5px 5px 0 var(--ink);transition:transform .2s}#fab:hover{transform:rotate(-6deg)}
#box{display:none;position:absolute;right:0;bottom:86px;width:min(370px,calc(100vw - 32px));height:min(540px,72vh);background:var(--bg);color:var(--ink);border:1px solid var(--line);box-shadow:8px 8px 0 var(--blue);flex-direction:column;overflow:hidden}
#box.on{display:flex}
.hd{background:var(--ink);color:var(--bg);padding:14px 18px;display:flex;justify-content:space-between;align-items:center}
.hd b{font:900 italic 20px var(--d)}.hd a{background:var(--blue);color:#fff;padding:4px 12px;font:600 11px var(--b);letter-spacing:.14em;text-transform:uppercase}
#log{flex:1;overflow:auto;padding:16px 18px;display:flex;flex-direction:column;gap:10px}
.m{max-width:88%;font-size:15px;line-height:1.5;white-space:pre-line;border:1px solid var(--line);padding:8px 14px}
.m.u{align-self:flex-end;background:var(--blue);color:#fff;border-color:var(--blue)}
.qc{display:flex;flex-wrap:wrap;gap:6px;padding:0 18px 10px}
.qc button{border:1px solid var(--line);background:none;padding:3px 12px;font:500 12px var(--b);letter-spacing:.08em;cursor:pointer}.qc button:hover{background:var(--ink);color:var(--bg)}
#f{display:flex;border-top:1px solid var(--line)}
#f input{flex:1;min-width:0;border:0;background:none;color:var(--ink);padding:14px 18px;font:16px var(--b)}#f input:focus{outline:0}
#f button{border:0;background:var(--ink);color:var(--bg);padding:0 20px;font:600 12px var(--b);letter-spacing:.14em;text-transform:uppercase;cursor:pointer}
:focus-visible{outline:3px solid var(--blue);outline-offset:3px}
@media(max-width:960px){#burger{display:block}.cta.nav{display:none}#menu{position:fixed;inset:0;top:calc(58px + env(safe-area-inset-top,0px));background:var(--bg);flex-direction:column;gap:0;padding:20px 4vw;font:900 italic 44px/1.4 var(--d);text-transform:none;letter-spacing:-.02em;transform:translateY(-110%);transition:transform .5s cubic-bezier(.7,0,.2,1);z-index:55}#menu.open{transform:none}#menu a{border:0;border-bottom:1px solid var(--line)}.cover{grid-template-columns:1fr}.two{grid-template-columns:1fr}.row{grid-template-columns:56px 1fr}.row b{grid-column:2}.row .no{font-size:42px}.form{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
</head>
<body>
<header class="top"><div class="bar">
  <a class="brand" href="#beranda">Visage</a>
  <nav id="menu" aria-label="Menu utama"><a href="#beranda">Beranda</a><a href="#portofolio">Portofolio</a><a href="#layanan">Layanan</a><a href="#tentang">Tentang</a><a href="#jurnal">Jurnal</a><a href="#kontak">Kontak</a></nav>
  <a class="cta nav" href="#kontak">Booking</a><button id="burger" aria-expanded="false">MENU</button>
</div></header>

<main>
<section class="pg" data-p="beranda">
  <div class="mast" aria-hidden="true">VISAGE</div>
  <div class="cover">
    <div class="l"><span class="kick">Makeup editorial · Surabaya</span><p>Riasan yang dirancang seperti halaman majalah: komposisi, cahaya, dan satu warna yang berani. Oleh Rima Ayu.</p><a class="cta" href="#portofolio">Lihat portofolio</a> <a class="cta o" href="#kontak">Booking</a></div>
    <div class="eyewrap" aria-hidden="true">
      <svg class="eye" viewBox="0 -20 300 190"><defs><clipPath id="al"><path d="M10 80C60 15 240 15 290 80C240 145 60 145 10 80Z"/></clipPath></defs>
        <path d="M2 82C20-12 280-12 298 82C240 28 60 28 2 82Z" fill="var(--blue)"/>
        <path d="M10 80C60 15 240 15 290 80C240 145 60 145 10 80Z" fill="#fff"/>
        <g clip-path="url(#al)"><g id="iris"><circle cx="150" cy="80" r="46" fill="var(--blue)"/><circle cx="150" cy="80" r="18" fill="#0B0B0F"/><circle cx="138" cy="66" r="7" fill="#fff"/></g></g>
        <path d="M10 80C60 15 240 15 290 80C240 145 60 145 10 80Z" fill="none" stroke="#0B0B0F" stroke-width="5"/>
        <path d="M38 50L18 26M74 34L62 6M112 26L106-2M150 22V-6M188 26L194-2M226 34L238 6M262 50L282 26" stroke="#0B0B0F" stroke-width="5" stroke-linecap="round"/></svg>
    </div>
    <ul class="cl"><li><small>Sampul</small>Kulit seperti kaca, tanpa terlihat berlebihan</li><li><small>Tren</small>Eyeshadow kobalt: berani atau bijak?</li><li><small>Profil</small>Rima Ayu, 8 tahun merias bintang dan pengantin</li></ul>
  </div>
  <div class="tick" aria-hidden="true"><span>Bridal — Editorial — Avant-garde — Natural — Photoshoot — Wisuda — Bridal — Editorial — Avant-garde — Natural — Photoshoot — Wisuda — </span></div>
</section>

<section class="pg" data-p="portofolio"><div class="wrap">
  <span class="kick">Arsip karya</span><h1 class="ph">Portofolio</h1>
  <div class="chips" id="fc"></div><div class="mas" id="mas"></div>
</div></section>

<section class="pg" data-p="layanan"><div class="wrap">
  <span class="kick">Daftar isi</span><h1 class="ph">Layanan</h1>
  <div class="toc" id="toc"></div>
</div></section>

<section class="pg" data-p="tentang"><div class="wrap">
  <span class="kick">Profil</span><h1 class="ph">Tentang Rima</h1>
  <div class="two"><div class="port" aria-hidden="true"></div>
  <div><div class="cols"><p>Rima Ayu memulai karier di belakang panggung peragaan busana lokal, tempat ia belajar bahwa riasan terbaik bukan menutupi, melainkan menegaskan karakter.</p><p>Kini ia merias pengantin, model, dan tokoh publik di Surabaya dan sekitarnya, dengan pendekatan editorial: satu konsep, satu warna kuat, dan kulit yang tetap terlihat hidup.</p><p>Semua produk yang digunakan halal, bebas paraben, dan disesuaikan dengan jenis kulit setiap klien.</p></div>
  <div class="stats"><div><b>8</b><span>Tahun pengalaman</span></div><div><b>300+</b><span>Klien dirias</span></div><div><b>40</b><span>Pemotretan editorial</span></div></div></div></div>
  <p class="pull">“Riasan terbaik membuatmu terlihat seperti dirimu, dalam cahaya terbaik.”</p>
</div></section>

<section class="pg" data-p="jurnal"><div class="wrap">
  <span class="kick">Tulisan terbaru</span><h1 class="ph">Jurnal</h1>
  <div class="jur" id="jur"></div>
</div></section>

<section class="pg" data-p="kontak"><div class="wrap">
  <span class="kick">Booking</span><h1 class="ph">Kontak</h1>
  <div class="two"><div class="form">
    <label class="f">Layanan<select id="sv"></select></label>
    <label>Tanggal acara<input type="date" id="dt"></label><label>Nama<input id="nm" placeholder="Nama lengkap"></label>
    <label class="f">Lokasi acara<input id="lc" placeholder="Kota atau venue"></label>
    <label class="f">Catatan<textarea id="nt" rows="2" placeholder="Tema, warna busana, referensi..."></textarea></label>
    <div class="f"><button class="cta" id="go" style="padding:16px 34px">Kirim ke WhatsApp</button></div></div>
  <div class="info"><h3>Studio Visage</h3><p>Surabaya, Jawa Timur<br>Senin–Sabtu, 08.00–18.00 WIB<br>Instagram @visage.by.rima</p><p>Home service tersedia di Surabaya dan Sidoarjo. Luar kota dengan biaya transport dan akomodasi.</p></div></div>
</div></section>
</main>

<footer><span>© 2026 Visage by Rima Ayu</span><span>Ganti nomor WA, layanan, dan harga di bagian CONFIG pada kode.</span></footer>

<div id="bot">
  <div id="box" role="dialog" aria-label="Chat Visage">
    <div class="hd"><b>Asisten Visage</b><a href="#" id="toWA">Lanjut ke WA</a></div>
    <div id="log"></div><div class="qc" id="chips"></div>
    <form id="f"><input id="in" placeholder="Tanya layanan, harga, jadwal..." autocomplete="off" aria-label="Pesan"><button>Kirim</button></form>
  </div>
  <button id="fab" aria-label="Buka chat">V</button>
</div>

<script>
/* ===== CONFIG ===== */
const WA="6281234567890"; // format 62..., tanpa + atau 0
const S=[
 {id:"bridal",n:"Bridal",d:"Akad dan resepsi, uji coba look, touch-up sepanjang acara.",p:3500000,u:"mulai"},
 {id:"editorial",n:"Editorial",d:"Riasan konsep untuk majalah, lookbook, dan kampanye brand.",p:2500000,u:"mulai"},
 {id:"akad",n:"Akad dan Lamaran",d:"Riasan natural tahan 8 jam dengan bulu mata dan hairdo sederhana.",p:1800000,u:"mulai"},
 {id:"wisuda",n:"Wisuda dan Pesta",d:"Look segar dan bersih, selesai dalam 90 menit.",p:750000,u:"mulai"},
 {id:"kelas",n:"Kelas Privat",d:"Belajar merias diri 2 jam dengan catatan produk.",p:900000,u:"per sesi"}];
const W=[["Cobalt Tears","Editorial","linear-gradient(160deg,#1F2BFF,#0b0f7a)","#F1C7B5","50%"],["Kebaya Embun","Bridal","linear-gradient(160deg,#F1C7B5,#d89c86)","#fff","999px"],["Noir Lash","Avant-garde","linear-gradient(160deg,#222,#000)","#F2506E","0"],["Kulit Kaca","Natural","linear-gradient(160deg,#f3e3d8,#e0b9a4)","#1F2BFF","50% 0"],["Akad Senja","Bridal","linear-gradient(160deg,#c9704f,#7a2e1e)","#F7D9A5","50%"],["Metal Bibir","Editorial","linear-gradient(160deg,#9aa4ff,#3a45d6)","#e8e8ee","999px 999px 0 0"],["Rona Pagi","Natural","linear-gradient(160deg,#ffd9cc,#f3a58f)","#fff","50%"],["Garis Kobalt","Avant-garde","linear-gradient(160deg,#fff,#d8d8e4)","#1F2BFF","0 50%"]];
const A=[["Tips","Cara merawat kulit sebelum hari H","Mulai 4 minggu sebelumnya: bersihkan lembut, pakai pelembap, tabir surya setiap hari, dan hindari produk baru menjelang acara. Kulit yang tenang membuat riasan terlihat menyatu."],["Tren","Eyeshadow kobalt: berani atau bijak?","Biru kobalt terlihat segar di kulit sawo matang jika dipadukan dengan bibir nude dan alis lembut. Tahan di kelopak, jangan sampai ke tulang pipi."],["Panduan","Memilih look sesuai kebaya","Kebaya putih cocok dengan rona hangat, kebaya berwarna gelap cocok dengan bibir berani. Bawa potongan kain saat konsultasi agar warnanya tepat."]];
const rp=n=>"Rp"+n.toLocaleString("id-ID"),$=s=>document.querySelector(s);
const wa=t=>"https://wa.me/"+WA+"?text="+encodeURIComponent(t);
/* router hash */
const PGS=[...document.querySelectorAll(".pg")].map(p=>p.dataset.p);
function route(){const h=(location.hash||"#beranda").slice(1);const id=PGS.includes(h)?h:"beranda";
 document.querySelectorAll(".pg").forEach(p=>p.classList.toggle("on",p.dataset.p==id));
 document.querySelectorAll("#menu a").forEach(a=>a.classList.toggle("on",a.getAttribute("href")=="#"+id));
 $("#menu").classList.remove("open");$("#burger").setAttribute("aria-expanded","false");scrollTo(0,0)}
addEventListener("hashchange",route);route();
$("#burger").onclick=()=>{const o=$("#menu").classList.toggle("open");$("#burger").setAttribute("aria-expanded",o)};
const go=id=>{if(location.hash=="#"+id)route();else location.hash=id};
/* mata mengikuti kursor */
addEventListener("pointermove",e=>{const ir=$("#iris"),sv=ir&&ir.ownerSVGElement;if(!sv||!sv.getClientRects().length)return;const r=sv.getBoundingClientRect(),a=Math.atan2(e.clientY-(r.top+r.height/2),e.clientX-(r.left+r.width/2)),d=Math.min(34,Math.hypot(e.clientX-r.left-r.width/2,e.clientY-r.top-r.height/2)/9);ir.style.transform=`translate(${Math.cos(a)*d}px,${Math.sin(a)*d*.45}px)`});
/* portofolio */
const cats=["Semua",...new Set(W.map(x=>x[1]))];
$("#fc").replaceChildren(...cats.map((c,i)=>{const b=document.createElement("button");b.type="button";b.className=i?"":"on";b.dataset.c=c;b.textContent=c;return b;}));
function showW(c){const mas=$("#mas");mas.replaceChildren(...W.map((x,i)=>({x,i})).filter(o=>c=="Semua"||o.x[1]==c).map(({x,i})=>{const card=document.createElement("div");card.className="sp";card.dataset.n="0"+(i+1);card.style.setProperty("--g",x[2]);card.style.setProperty("--s",x[3]);card.style.setProperty("--r",x[4]);card.style.minHeight=[300,420,360,480][i%4]+"px";card.appendChild(document.createElement("i"));const copy=document.createElement("div"),title=document.createElement("b"),kind=document.createElement("small");title.textContent=x[0];kind.textContent=x[1];copy.append(title,kind);card.appendChild(copy);return card;}));}
showW("Semua");
$("#fc").onclick=e=>{const b=e.target.closest("button");if(!b)return;document.querySelectorAll("#fc button").forEach(x=>x.classList.toggle("on",x==b));showW(b.dataset.c)};
/* layanan + jurnal */
$("#toc").replaceChildren(...S.map((x,i)=>{const row=document.createElement("button");row.type="button";row.className="row";row.dataset.s=x.id;const no=document.createElement("span");no.className="no";no.textContent="0"+(i+1);const copy=document.createElement("div"),title=document.createElement("h3"),desc=document.createElement("p"),price=document.createElement("b");title.textContent=x.n;desc.textContent=x.d;price.textContent=rp(x.p);copy.append(title,desc);row.append(no,copy,price);return row;}));
$("#sv").replaceChildren(...S.map(x=>{const option=document.createElement("option");option.value=x.id;option.textContent=x.n;return option;}));
const sv=()=>S.find(x=>x.id==$("#sv").value);
function pick(id){$("#sv").value=id}
$("#toc").onclick=e=>{const b=e.target.closest(".row");if(b){pick(b.dataset.s);go("kontak")}};
$("#jur").replaceChildren(...A.map(a=>{const art=document.createElement("article");art.className="art";const small=document.createElement("small"),title=document.createElement("h3"),details=document.createElement("details"),summary=document.createElement("summary"),copy=document.createElement("p");small.textContent=a[0];title.textContent=a[1];summary.textContent="Baca selengkapnya";copy.textContent=a[2];details.append(summary,copy);art.append(small,title,details);return art;}));
$("#go").onclick=()=>{const d=$("#dt").value,s=sv();window.open(wa("Halo Visage, saya mau booking makeup.\nLayanan: "+s.n+" ("+s.u+" "+rp(s.p)+")\nTanggal: "+(d?new Date(d).toLocaleDateString("id-ID",{day:"numeric",month:"long",year:"numeric"}):"belum pasti")+"\nLokasi: "+($("#lc").value||"-")+"\nNama: "+($("#nm").value||"-")+"\nCatatan: "+($("#nt").value||"-")+"\nApakah tanggal tersebut masih tersedia?"),"_blank","noopener,noreferrer")};
/* ===== Chatbot ===== */
const box=$("#box"),log=$("#log"),inp=$("#in"),hist=[];let hi=false;
const KB=[
 [/layanan|jasa|paket/,()=>"Layanan kami:\n"+S.map(x=>"• "+x.n+" "+rp(x.p)).join("\n")+"\nKetik “saya mau bridal” untuk memilihnya."],
 [/harga|biaya|tarif|berapa/,()=>S.map(x=>x.n+": "+x.u+" "+rp(x.p)).join("\n")],
 [/dp|bayar|pembayaran|booking/,()=>"Booking cukup DP 30% untuk mengunci tanggal, pelunasan H-3. Isi form Kontak atau tekan “Lanjut ke WA”."],
 [/area|lokasi|datang|luar kota|home service|studio/,()=>"Home service di Surabaya dan Sidoarjo, atau di studio. Luar kota bisa dengan biaya transport dan akomodasi."],
 [/produk|halal|alergi|sensitif|kulit/,()=>"Produk halal, bebas paraben, disesuaikan dengan jenis kulit. Sampaikan alergi saat konsultasi."],
 [/tahan|awet|luntur|jam/,()=>"Riasan dirancang tahan hingga 8 jam, tahan keringat dan air mata. Paket Bridal sudah termasuk touch-up."],
 [/uji|trial|coba|konsultasi/,()=>"Uji coba look tersedia untuk Bridal dan Akad, 2–4 minggu sebelum acara. Konsultasi awal gratis lewat WhatsApp."],
 [/portofolio|karya|hasil|foto/,()=>{go("portofolio");return"Kubuka halaman Portofolio ya. Kamu bisa filter berdasarkan kategori."}],
 [/tentang|siapa|profil|rima/,()=>{go("tentang");return"Kubuka halaman Tentang. Rima Ayu sudah 8 tahun merias, mulai dari bridal sampai editorial."}],
 [/jurnal|artikel|tips|blog/,()=>{go("jurnal");return"Kubuka halaman Jurnal berisi tips dan tren riasan."}],
 [/kontak|hubungi|alamat/,()=>{go("kontak");return"Kubuka halaman Kontak, lengkap dengan form booking."}],
 [/rekomen|bingung|saran|cocok/,()=>"Ceritakan tema acara dan warna busanamu, Rima akan memilihkan look-nya. Mau dihubungkan ke WhatsApp?"],
 [/halo|hai|hi\b|pagi|siang|malam/,()=>"Halo! Aku asisten Visage. Mau lihat karya, layanan, atau langsung booking?"]
];
function add(t,u){const d=document.createElement("div");d.className="m"+(u?" u":"");d.textContent=t;log.appendChild(d);log.scrollTop=log.scrollHeight}
function ask(t){if(!t.trim())return;add(t,1);hist.push("Saya: "+t);const l=t.toLowerCase();let a;
 const it=S.find(x=>l.includes(x.id)||l.includes(x.n.split(" ")[0].toLowerCase()));
 if(it&&/mau|ingin|pilih|booking|pesan/.test(l)){pick(it.id);go("kontak");a=it.n+" sudah dipilih dan form Kontak kubuka. Lengkapi tanggal dan lokasi, atau tekan “Lanjut ke WA”."}
 else if(it)a=it.n+": "+it.d+" "+it.u+" "+rp(it.p)+"."
 else{const k=KB.find(([r])=>r.test(l));a=k?k[1]():"Pertanyaan itu paling pas dijawab Rima langsung. Tekan “Lanjut ke WA” di atas ya."}
 setTimeout(()=>{add(a);hist.push("Asisten: "+a)},450)}
$("#fab").onclick=()=>{if(box.classList.toggle("on")&&!hi){hi=true;add("Halo! Aku asisten Visage. Aku bisa bantu soal layanan, harga, jadwal, atau membuka halaman yang kamu cari.");$("#chips").replaceChildren(...["Lihat layanan","Portofolio","Harga","DP & booking","Area"].map(c=>{const b=document.createElement("button");b.type="button";b.textContent=c;return b;}));}};
$("#chips").onclick=e=>{if(e.target.tagName=="BUTTON")ask(e.target.textContent)};
$("#f").onsubmit=e=>{e.preventDefault();ask(inp.value);inp.value=""};
$("#toWA").onclick=e=>{e.preventDefault();window.open(wa("Halo Visage, saya lanjut dari chat website:\n"+(hist.slice(-6).join("\n")||"Saya ingin konsultasi makeup.")+"\nLayanan terpilih: "+sv().n),"_blank","noopener,noreferrer")};
</script>
